import type { GenerateRequest, GenerateResponse } from '../../shared/types';

// ──── Model map — use the actual available models on this account ────
const MODELS = {
  standard: '@cf/meta/llama-3.2-3b-instruct',
  quality: '@cf/mistral/mistral-7b-instruct-v0.2-lora',
} as const;

// ──── Environment bindings ────
export interface Env {
  AI: Ai;
  DB: D1Database;
  LMS_CACHE: KVNamespace;
}

// ──── Budget row shape ────
interface BudgetRow {
  org_id: string;
  monthly_token_cap: number;
  tokens_used_this_period: number;
  billing_period_start: number;
}

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);

    // ── GET /health — model connectivity check ──
    if (req.method === 'GET' && url.pathname === '/health') {
      const budget = await getBudget(env.DB, url.searchParams.get('org_id') || 'demo');
      return json({
        status: 'ok',
        models: Object.values(MODELS),
        budget: budget ? {
          org_id: budget.org_id,
          monthly_cap: budget.monthly_token_cap,
          used: budget.tokens_used_this_period,
          remaining: Math.max(0, budget.monthly_token_cap - budget.tokens_used_this_period),
        } : null,
      }, 200);
    }

    // ── GET /budget?org_id=... — budget status for dashboard ──
    if (req.method === 'GET' && url.pathname === '/budget') {
      const orgId = url.searchParams.get('org_id') || 'demo';
      const budget = await getBudget(env.DB, orgId);
      return json(budget ? {
        org_id: budget.org_id,
        monthly_cap: budget.monthly_token_cap,
        used: budget.tokens_used_this_period,
        remaining: Math.max(0, budget.monthly_token_cap - budget.tokens_used_this_period),
      } : { error: 'no_budget_found', org_id: orgId }, 200);
    }

    if (req.method !== 'POST') {
      return json({ error: 'method_not_allowed' }, 405);
    }

    // POST /stream — streaming LLM response
    if (url.pathname === '/stream') {
      return handleStream(req, env);
    }

    if (url.pathname !== '/generate') {
      return json({ error: 'not_found' }, 404);
    }

    let body: GenerateRequest;
    try {
      body = await req.json();
    } catch {
      return json({ error: 'invalid_json' }, 400);
    }

    // Validate
    if (!body.messages?.length) {
      return json({ error: 'missing_field', field: 'messages' }, 400);
    }
    if (!body.tier || !['standard', 'quality'].includes(body.tier)) {
      return json({ error: 'invalid_tier', valid: ['standard', 'quality'] }, 400);
    }
    if (!body.org_id) {
      return json({ error: 'missing_field', field: 'org_id' }, 400);
    }

    // ── 1. Budget check ──
    await ensureBudget(env.DB, body.org_id);
    const budget = await getBudget(env.DB, body.org_id);
    const exhausted = budget && budget.tokens_used_this_period >= budget.monthly_token_cap;

    if (exhausted) {
      return json(
        {
          error: 'budget_exhausted',
          message: 'Contact your org admin to increase the budget.',
        },
        429,
      );
    }

    // ── 2. Call Workers AI ──
    const model = MODELS[body.tier];
    const maxTokens = body.tier === 'quality' ? 2048 : 1024;

    let aiResult: AiTextGenerationOutput;
    try {
      aiResult = (await env.AI.run(model, {
        messages: body.messages,
        max_tokens: maxTokens,
      })) as AiTextGenerationOutput;
    } catch (err) {
      console.error('Workers AI error:', err);
      return json({ error: 'ai_call_failed', detail: String(err) }, 502);
    }

    // ── 3. Track tokens ──
    const tokensUsed = aiResult.usage?.total_tokens ?? 0;
    const throttle = budget
      ? budget.tokens_used_this_period + tokensUsed >= budget.monthly_token_cap
      : false;

    await trackTokens(env.DB, body.org_id, tokensUsed);

    // ── 4. Return ──
    const response: GenerateResponse = {
      response: aiResult.response ?? '',
      model_used: model,
      provider: 'cloudflare',
      tokens_used: tokensUsed,
      throttle_warning: throttle,
    };

    return json(response, 200);
  },
};

// ════════════════════════════════════════════════════════
//  POST /stream — SSE streaming
// ════════════════════════════════════════════════════════

async function handleStream(req: Request, env: Env): Promise<Response> {
  let body: GenerateRequest;
  try {
    body = await req.json();
  } catch {
    return json({ error: 'invalid_json' }, 400);
  }

  if (!body.messages?.length) {
    return json({ error: 'missing_field', field: 'messages' }, 400);
  }
  if (!body.tier || !['standard', 'quality'].includes(body.tier)) {
    return json({ error: 'invalid_tier', valid: ['standard', 'quality'] }, 400);
  }
  if (!body.org_id) {
    return json({ error: 'missing_field', field: 'org_id' }, 400);
  }

  // Budget check
  await ensureBudget(env.DB, body.org_id);
  const budget = await getBudget(env.DB, body.org_id);
  if (budget && budget.tokens_used_this_period >= budget.monthly_token_cap) {
    return json({ error: 'budget_exhausted' }, 429);
  }

  const model = MODELS[body.tier];
  const maxTokens = body.tier === 'quality' ? 2048 : 1024;

  try {
    // Workers AI streaming — returns a ReadableStream
    const aiStream = (await env.AI.run(model, {
      messages: body.messages,
      stream: true,
      max_tokens: maxTokens,
    })) as ReadableStream;

    // Wrap in SSE (Server-Sent Events) format
    const sseStream = aiStreamToSSE(aiStream, env.DB, body.org_id);

    return new Response(sseStream, {
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
      },
    });
  } catch (err) {
    console.error('Stream error:', err);
    return json({ error: 'ai_call_failed', detail: String(err) }, 502);
  }
}

// Transform Workers AI stream → SSE with token tracking
function aiStreamToSSE(
  stream: ReadableStream,
  db: D1Database,
  orgId: string
): ReadableStream {
  let fullResponse = '';
  let tokenCount = 0;
  const encoder = new TextEncoder();

  // Use pipeThrough to handle Workers AI SSE format natively
  const [workersOut, consumerIn] = stream.tee();

  // Side-reader: accumulates full response for the final "done" event
  const reader = workersOut.getReader();
  const decoder = new TextDecoder();

  // Read the Workers AI stream in the background to accumulate tokens
  const accumulatePromise = (async () => {
    let buffer = '';
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';
        for (const line of lines) {
          if (line.startsWith('data: ') && !line.includes('[DONE]')) {
            try {
              const chunk = JSON.parse(line.slice(6));
              if (chunk.response) {
                fullResponse += chunk.response;
                tokenCount++;
              }
            } catch { /* skip */ }
          }
        }
      }
    } catch { /* best-effort */ }
  })();

  // Transform each Workers AI SSE chunk into our SSE format
  const transformer = new TransformStream<Uint8Array, Uint8Array>({
    transform(chunk, controller) {
      const text = decoder.decode(chunk, { stream: true });
      const lines = text.split('\n').filter(Boolean);
      for (const line of lines) {
        if (line.startsWith('data: ') && !line.includes('[DONE]')) {
          try {
            const parsed = JSON.parse(line.slice(6));
            if (parsed.response) {
              const msg = JSON.stringify({ type: 'token', text: parsed.response });
              controller.enqueue(encoder.encode(`data: ${msg}\n\n`));
            }
          } catch { /* skip */ }
        }
      }
    },
    async flush(controller) {
      // Wait for accumulation to finish
      await accumulatePromise;
      // Send final done event
      const doneMsg = JSON.stringify({
        type: 'done',
        response: fullResponse,
        tokens_used: tokenCount,
      });
      controller.enqueue(encoder.encode(`data: ${doneMsg}\n\n`));
      // Track tokens async
      if (tokenCount > 0) {
        trackTokens(db, orgId, tokenCount).catch(() => {});
      }
    },
  });

  return consumerIn.pipeThrough(transformer);
}

// ──── Helpers ────

const DEFAULT_MONTHLY_CAP = 100000;

async function ensureBudget(db: D1Database, orgId: string): Promise<void> {
  await db
    .prepare(
      `INSERT OR IGNORE INTO org_budgets (org_id, monthly_token_cap, tokens_used_this_period, billing_period_start)
       VALUES (?, ?, 0, unixepoch())`
    )
    .bind(orgId, DEFAULT_MONTHLY_CAP)
    .run();
}

async function getBudget(db: D1Database, orgId: string): Promise<BudgetRow | null> {
  const result = await db
    .prepare('SELECT * FROM org_budgets WHERE org_id = ?')
    .bind(orgId)
    .first<BudgetRow>();
  return result ?? null;
}

async function trackTokens(db: D1Database, orgId: string, tokens: number): Promise<void> {
  await db
    .prepare(
      'UPDATE org_budgets SET tokens_used_this_period = tokens_used_this_period + ? WHERE org_id = ?',
    )
    .bind(tokens, orgId)
    .run();
}

function json(data: unknown, status: number): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

