describe('Observability', () => {
  it('emits tutor.embed and tutor.vectorize spans on HTTP ask', async () => {
    const { spans } = spyOnSpans();

    (env as any).VECTORIZE_INDEX.query = mockVectorizeQuery([
      matchingChunk({ lesson_id: 'l1', org_id: 'org-test' }),
    ]);
    (env as any).AI_GATEWAY = mockAiGateway(DEFAULT_LLM_RESPONSE);

    await ask({
      question: 'What is a variable?',
      learner_id: 'learner-1',
      lesson_id: 'l1',
      course_id: 'course-1',
      org_id: 'org-test',
    });

    const embed = spans('tutor.embed');
    const vectorize = spans('tutor.vectorize');

    expect(embed.length).toBeGreaterThan(0);
    expect(embed[0].duration_ms).toBeDefined();
    expect(embed[0].text_len).toBeGreaterThan(0);
    expect(embed[0].model).toBe('@cf/baai/bge-large-en-v1.5');

    expect(vectorize.length).toBeGreaterThan(0);
    expect(vectorize[0].duration_ms).toBeDefined();
    expect(vectorize[0].topK).toBe(50);
    expect(vectorize[0].scope).toBe('lesson');
    expect(vectorize[0].raw_matches).toBeGreaterThan(0);
  });

  it('emits tutor.ask and tutor.gateway spans on HTTP ask', async () => {
    const { spans } = spyOnSpans();

    (env as any).VECTORIZE_INDEX.query = mockVectorizeQuery([
      matchingChunk({ lesson_id: 'l1', org_id: 'org-test' }),
    ]);
    (env as any).AI_GATEWAY = mockAiGateway(DEFAULT_LLM_RESPONSE);

    await ask({
      question: 'What is a variable?',
      learner_id: 'learner-1',
      lesson_id: 'l1',
      course_id: 'course-1',
      org_id: 'org-test',
    });

    const askSpans = spans('tutor.ask');
    const gateway = spans('tutor.gateway');

    expect(askSpans.length).toBeGreaterThan(0);
    expect(askSpans[0].duration_ms).toBeDefined();
    expect(askSpans[0].citations).toBeGreaterThan(0);
    expect(askSpans[0].history_size).toBeGreaterThan(0);

    expect(gateway.length).toBeGreaterThan(0);
    expect(gateway[0].status).toBe(200);
    expect(gateway[0].tier).toBe('standard');
  });

  it('emits no_citations flag when Vectorize returns no matches', async () => {
    const { spans } = spyOnSpans();

    (env as any).VECTORIZE_INDEX.query = mockVectorizeQuery([]);

    await ask({
      question: 'What is a variable?',
      learner_id: 'learner-1',
      lesson_id: 'l1',
      course_id: 'course-1',
      org_id: 'org-test',
    });

    const askSpans = spans('tutor.ask');
    expect(askSpans.length).toBeGreaterThan(0);
    expect(askSpans[0].no_citations).toBe(true);
  });

  it('emits gateway_error flag on gateway failure', async () => {
    const { spans } = spyOnSpans();

    (env as any).VECTORIZE_INDEX.query = mockVectorizeQuery([
      matchingChunk({ lesson_id: 'l1', org_id: 'org-test' }),
    ]);
    (env as any).AI_GATEWAY = mockAiGateway({ error: 'down' }, false);

    await ask({
      question: 'What is a variable?',
      learner_id: 'learner-1',
      lesson_id: 'l1',
      course_id: 'course-1',
      org_id: 'org-test',
    });

    const askSpans = spans('tutor.ask');
    const gateway = spans('tutor.gateway');
    expect(askSpans[0].gateway_error).toBe(true);
    expect(gateway[0].status).toBe(502);
  });
});

